(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.02-t*0.27)*16 + Math.sin(x*0.016+t*0.33)*11;
  const w2x = Math.sin((x+y)*0.01+t*0.15)*8 + Math.cos((x-y)*0.012-t*0.18)*6;
  const w2y = Math.cos((x-y)*0.011+t*0.17)*7 + Math.sin((x+y)*0.009-t*0.2)*5;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.7],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.9],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 1.2],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+4)*50, 0.11, 2.1, 0.6],
    [400+Math.cos(t*0.55+2)*60, 220+Math.sin(t*0.75+1)*40, 0.085, 1.8, 1.05]
  ];
  let aS=0, iS=0, mS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave = Math.sin(d*f - t*sp);
    aS += wave * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * w;
    mS += Math.sin(d*f*0.4 - t*sp*0.3 + 2.8) * w * 0.5;
  }
  const n = 8;
  const act=aS/n, inh=iS/n, mod=mS/n;
  const bg1 = Math.sin(sx*0.04+sy*0.025+t*0.8);
  const bg2 = Math.sin(sx*0.03-sy*0.04+t*1.1);
  const bg3 = Math.sin((sx+sy)*0.12+t*2.5)*0.2;
  const bg4 = Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg5 = Math.sin(sx*0.08+t*1.5)*Math.cos(sy*0.06-t*1.2)*0.15;
  const bg = (bg1+bg2)/2 + bg3 + bg4 + bg5;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2);
  const ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.05-ang*3-t*1.5);
  const sp2 = Math.sin(dist*0.04+ang*4-t*1.2);
  const sp3 = Math.sin(dist*0.08-ang*2+t*0.9)*0.3;
  const spiral = (sp1+sp2)*0.4 + sp3;
  const lap = Math.sin(sx*0.2+t)*Math.sin(sy*0.2-t) + Math.sin((sx-sy)*0.15+t*0.7)*0.5;
  const rd1 = Math.tanh((act - inh*0.65 + bg*0.25 + spiral*0.4 + lap*0.15)*2.2);
  const rd2 = Math.tanh((inh - act*0.5 + mod + bg*0.15 - spiral*0.2)*1.8);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const vein = Math.tanh(Math.sin(ang*5+dist*0.03-t)*3)*0.15;
  const blend = rd1*0.55 + rd2*0.15 + cell*0.2 + vein*0.1;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[12,45,88],[18,95,115],[25,155,145],[45,185,130],
    [180,195,60],[215,155,50],[210,110,65],[175,60,70],[120,30,60],
    [60,15,48],[20,10,42],[5,12,52]
  ];
  const idx = v*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2);
  const f = idx-i;
  const r0=pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const g0=pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const b0=pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const lum = 0.82+Math.sin(rd1*Math.PI)*0.18;
  const edge = Math.abs(rd1)>0.65 ? 1.12 : (Math.abs(rd1)>0.4 ? 1.05 : 1.0);
  const glow = Math.max(0, 1-dist/220)*0.08*Math.sin(t*0.5)*Math.sin(rd1*2);
  const shift = rd2*8;
  return [
    Math.min(255, Math.max(0, (r0+shift)*lum*edge + glow*60))|0,
    Math.min(255, Math.max(0, (g0-shift*0.5)*lum*edge + glow*80))|0,
    Math.min(255, Math.max(0, (b0+shift*0.8)*lum*edge + glow*100))|0
  ];
}
